-- V14: 意图级 context_schema（预注入 collecting system prompt）
-- 执行：psql -d aierp -f constitution/add_workflow_context_schema.sql
-- 字段填充：python scripts/sync_workflow_context.py（写入 business.workflow_steps.fields）
--
-- 说明：流程步骤已迁移至表 business.workflow_steps（见 constitution/refactor_workflow_steps.sql）。
-- 本文件中各 UPDATE 的 JSON 仍含 steps 数组，便于对照与一次性初始化前的备份；
-- 运行时 collecting 以 workflow_steps 表为准，context_schema 此处主要保留 prompt_rules、allowed_tools。
-- V16：统一为 query_db / submit / ask_user 三原子工具，不再在文案中出现旧工具名。
BEGIN;

ALTER TABLE business.workflows
ADD COLUMN IF NOT EXISTS context_schema JSONB DEFAULT '{}'::jsonb;

COMMENT ON COLUMN business.workflows.context_schema IS '意图级上下文：steps/allowed_tools/prompt_rules，供 collecting 预注入 system prompt';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["你必须通过工具调用来完成任务，不要用文字描述你「将要做什么」然后等用户确认。", "当你已经通过 query_db 核对过必要信息后，且用户的新建意图明确、字段可映射时，立即调用 submit。系统会自动生成确认卡片给用户，不需要你用文字询问「是否确认」。", "禁止输出类似「请确认以下修改是否符合预期」这样的文字然后等待用户回复。直接调用工具，工具会触发确认流程。", "只有在信息确实不足（比如用户没说改成什么值、没指定哪条记录）时，才用 ask_user 工具追问。", "每一轮对话你必须至少调用一个工具（query_db / submit / ask_user），不要只输出文字。", "原则：能从用户本轮及历史输入中可靠推断的字段请自行填入 submit 的 data 中；不确定或缺关键信息时用 ask_user 追问；需要核对库中已有编号、枚举或关联记录时用 query_db（仅 SELECT business/meta）。", "若用户在一轮话里已给出产品编号、名称、品类、单位、单价等可映射到 meta 字段的信息，禁止再用纯文字追问或列举待填项，必须直接调用 submit（由系统弹出确认卡片）。", "用 query_db 查业务表时，除非用户明确要求查看已删除记录，否则 WHERE 条件应包含 deleted_at IS NULL；系统也会在未写 deleted_at 时自动过滤已删行。"], "steps": [{"seq": 1, "action": "collect", "label": "客户主数据（customers）", "table": "customers", "instruction": "用户要新建或操作客户时：用 query_db 核对名称/编码；字段齐全后调用 submit 提交。", "fields": []}, {"seq": 2, "action": "collect", "label": "联系人（contacts）", "table": "contacts", "instruction": "新建联系人：收集 contacts 字段；调用 submit 提交。", "fields": []}, {"seq": 3, "action": "collect", "label": "产品（products）", "table": "products", "instruction": "新建产品：收集 products 字段；product_name 为产品名称列；调用 submit 提交。", "fields": []}, {"seq": 4, "action": "submit", "label": "提交新建预览", "tool": "submit"}]}'::jsonb WHERE intent = 'create_simple_entity';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["你在帮用户修改已有记录。先用 query_db 找到目标记录并确认唯一性（必要时用 ask_user 让用户选定）；再使用 submit 提交要改的字段，触发确认（不直接 UPDATE）。", "需要核对编号、枚举或现值时只用 query_db（仅 SELECT business/meta）。", "用 query_db 查业务表时，除非用户明确要求查看已删除记录，否则 WHERE 条件应包含 deleted_at IS NULL；系统也会在未写 deleted_at 时自动过滤已删行。", "你必须通过工具调用来完成任务，不要用文字描述你「将要做什么」然后等用户确认。", "每一轮对话你必须至少调用一个工具，不要只输出文字。"], "steps": [{"seq": 1, "action": "lookup", "label": "查找客户", "table": "customers", "instruction": "用 query_db 在 business.customers 中按公司名称或 short_name 等定位记录，结果须唯一后再 submit。", "fields": []}, {"seq": 2, "action": "lookup", "label": "查找联系人", "table": "contacts", "instruction": "修改联系人前用 query_db 确认唯一记录与 id。", "fields": []}, {"seq": 3, "action": "lookup", "label": "查找产品", "table": "products", "instruction": "修改产品前用 query_db 确认唯一记录与 id；产品名称列为 product_name。", "fields": []}, {"seq": 4, "action": "collect", "label": "更新字段（customers）", "table": "customers", "instruction": "用户要改客户时：对 customers 使用 submit（record_id 须来自 query_db 唯一结果）。", "fields": []}, {"seq": 5, "action": "collect", "label": "更新字段（contacts）", "table": "contacts", "instruction": "用户要改联系人时：对 contacts 使用 submit。", "fields": []}, {"seq": 6, "action": "collect", "label": "更新字段（products）", "table": "products", "instruction": "用户要改产品时：对 products 使用 submit；产品名称列为 product_name。", "fields": []}, {"seq": 7, "action": "submit", "label": "提交更新预览", "tool": "submit"}]}'::jsonb WHERE intent = 'update_simple_entity';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["你在帮用户软删除已有记录。先用 query_db 找到目标记录并确认唯一性（必要时用 ask_user 让用户选定）；再使用 submit 提交删除请求，触发确认（不直接 UPDATE）。", "需要核对编号或现值时只用 query_db（仅 SELECT business/meta）。", "用 query_db 查业务表时，除非用户明确要求查看已删除记录，否则 WHERE 条件应包含 deleted_at IS NULL。", "你必须通过工具调用来完成任务。每一轮至少调用一个工具，不要只输出文字。"], "steps": [{"seq": 1, "action": "lookup", "label": "查找待删记录（客户）", "table": "customers", "instruction": "用 query_db 确认目标行唯一且含 id。", "fields": []}, {"seq": 2, "action": "lookup", "label": "查找待删记录（联系人）", "table": "contacts", "instruction": "同上。", "fields": []}, {"seq": 3, "action": "lookup", "label": "查找待删记录（产品）", "table": "products", "instruction": "同上。", "fields": []}, {"seq": 4, "action": "submit", "label": "提交软删预览", "tool": "submit"}]}'::jsonb WHERE intent = 'delete_simple_entity';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "ask_user"], "prompt_rules": ["本任务为只读查询，不要调用 write_entity、update_entity、delete_entity。", "使用 query_db 执行 SELECT，仅 business / meta schema；查询结果会在界面以表格展示，回复中请用自然语言简要说明要点。", "查询业务表时 WHERE 条件应包含 deleted_at IS NULL（除非用户明确要求查看已删除记录）；系统也会在未写 deleted_at 时自动过滤已删行。", "若用户意图模糊或缺少表名/条件，用 ask_user 追问。", "每一轮至少调用 query_db 或 ask_user 之一，不要只输出文字而不查库。"], "steps": [{"seq": 1, "action": "lookup", "label": "客户与联系人", "table": "customers", "instruction": "只读：可查询 customers、contacts 等；JOIN 时参考字段名与关联。", "fields": []}, {"seq": 2, "action": "lookup", "label": "产品", "table": "products", "instruction": "只读：products.product_name 为产品名称列。", "fields": []}, {"seq": 3, "action": "lookup", "label": "合同与明细", "table": "contracts", "instruction": "只读：contracts 与 contract_items、customers 等关联查询。", "fields": []}, {"seq": 4, "action": "lookup", "label": "合同模板与变更", "table": "contract_templates", "instruction": "只读：contract_templates、contract_changes 等。", "fields": []}]}'::jsonb WHERE intent = 'query_master_data';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["你必须通过工具完成任务，不要用纯文字代替工具调用。", "信息足够后必须调用 submit 一次性提交主表与明细，由系统弹出确认卡片；不要用文字询问「是否确认」。", "只有在缺客户、缺明细、或条件模糊时，才用 ask_user 追问。", "用 query_db 查 customers 时，对 name 或 short_name 使用 ILIKE ''%关键词%'' 模糊匹配，不要仅用精确匹配。", "每一轮至少调用 query_db、submit 或 ask_user 之一，不要只输出文字。", "【禁止】对 contracts 表直接调用旧工具；新建合同必须使用 submit 提交。", "不要向用户索要 contract_no；编号由系统按 CT-YYYYMM-NNN 生成。", "不要向用户索要每条 amount 或主表 total_amount；amount = quantity × unit_price，总额由系统汇总。", "currency 默认 CNY；用户未说明币种则不必追问。", "付款方式、交货日期、签约日期为可选字段，用户未提供时不追问，直接调用 submit 提交。"], "steps": [{"seq": 1, "action": "lookup", "label": "确认客户", "table": "customers", "instruction": "用 ILIKE 模糊匹配客户名称；取得 id（作为 customer_id）与客户名称（作 customer_name）。", "fields": []}, {"seq": 2, "action": "collect", "label": "收集合同主表", "table": "contracts", "instruction": "收集 contracts 主表信息（勿填 contract_no、total_amount 等系统字段）。", "fields": []}, {"seq": 3, "action": "collect", "label": "收集合同明细", "table": "contract_items", "instruction": "至少一行明细：product_name、quantity、unit_price；勿传 amount。", "fields": []}, {"seq": 4, "action": "lookup", "label": "核对产品", "table": "products", "instruction": "用 query_db 查 products 填写 product_code、product_id；名称列 product_name。", "fields": []}, {"seq": 5, "action": "submit", "label": "提交合同预览", "tool": "submit"}]}'::jsonb WHERE intent = 'create_contract';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["先用 query_db 查询 business.contracts / contract_items，确认合同存在且唯一。", "必须问清变更原因；无原因不得 submit（reason 必填）。", "条件满足后调用 submit 提交变更；不要用纯文字代替工具。", "可用工具：query_db、submit、ask_user。", "每一轮至少调用其一工具，不要只输出文字。"], "steps": [{"seq": 1, "action": "lookup", "label": "定位当前合同", "table": "contracts", "instruction": "用 query_db 拉取 contracts 与 contract_items 当前值；确认 contract_id。", "fields": []}, {"seq": 2, "action": "collect", "label": "收集变更内容", "table": "contract_items", "instruction": "弄清主表字段与明细增删改；变更原因 reason 必填。", "fields": []}, {"seq": 3, "action": "submit", "label": "提交变更预览", "tool": "submit"}]}'::jsonb WHERE intent = 'update_contract';

UPDATE business.workflows SET context_schema = '{"allowed_tools": ["query_db", "submit", "ask_user"], "prompt_rules": ["先用 query_db 确认要删除的合同（结果须唯一一行且含 id）。", "必须问清删除原因；调用 submit 提交删除请求（系统已知目标表为 contracts），且 explanation 填写删除原因（必填）。", "可用工具：query_db、submit、ask_user。", "每一轮至少调用其一工具，不要只输出文字。"], "steps": [{"seq": 1, "action": "lookup", "label": "定位待删合同", "table": "contracts", "instruction": "用 query_db 确认目标合同唯一。", "fields": []}, {"seq": 2, "action": "collect", "label": "确认删除原因", "table": "contracts", "instruction": "向用户确认删除原因，explanation 必填。", "fields": []}, {"seq": 3, "action": "submit", "label": "提交删除预览", "tool": "submit"}]}'::jsonb WHERE intent = 'delete_contract';

COMMIT;
